def _resolve_dataloader_collate_fn(self, ds: Optional[Input]) -> Optional[Callable]:
    if not ds:
        return None
    if isinstance(ds.transform, InputTransform):
        return ds._create_dataloader_collate_fn([self.data_fetcher])
    return default_collate

